"""Build a standalone local research viewer for compiled measurement artifacts."""
import argparse
import json
import subprocess
from pathlib import Path
from building_workflow.config import ROOT


def main():
    p=argparse.ArgumentParser();p.add_argument('run',type=Path);args=p.parse_args();run=args.run.resolve()
    subprocess.run(['node','--input-type=module','-e',"import esbuild from 'esbuild';await esbuild.build({entryPoints:['runtime/measured-viewer.mjs'],bundle:true,format:'iife',platform:'browser',outfile:"+json.dumps(str(run/'measured-viewer.js'))+"});"],cwd=ROOT,check=True)
    (run/'viewer.html').write_text('''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Measured urban reconstruction</title><style>body{margin:0;background:#e9eeed;font:14px system-ui}canvas{position:fixed;width:100vw!important;height:100vh!important;object-fit:contain}header{position:fixed;z-index:2;left:18px;top:18px;max-width:520px;padding:16px 20px;background:#142d36ed;color:#e6edf0;border-radius:12px}h1{font-size:20px;margin:0 0 8px}p{line-height:1.5;margin:8px 0}label{display:inline-block;margin:4px 8px 4px 0}select,button{font:inherit;padding:5px;border-radius:5px}a{color:#9bd1e8}footer{position:fixed;bottom:12px;left:18px;right:18px;z-index:2;color:#e6edf0;display:flex;justify-content:space-between;gap:12px}footer span{padding:9px 14px;background:#142d36ed;border-radius:8px}</style><header><h1>Tái tạo từ dữ liệu đo</h1><p>Google 3D Tiles + OSM → bề mặt tái tạo và ảnh chiếu có kiểm tra độ sâu. Không hiển thị tiles gốc trong viewer này.</p><label>Hình học <select id="variant"><option value="regularized">Làm sạch cục bộ</option><option value="measured">Mẫu đo gốc</option></select></label><label>Bề mặt <select id="mode"><option value="source">Ảnh nguồn (có ánh sáng baked)</option><option value="relight">Chiếu sáng lại — thử nghiệm</option><option value="geometry">Kiểm tra hình học</option><option value="coverage">Kiểm tra vùng thiếu ảnh</option></select></label><label>Công trình <select id="object"><option value="">Toàn cảnh</option></select></label><div><button data-view="overview">Tổng quan</button><button data-view="north">Góc khác</button><button data-view="top">Topdown</button><select id="source-camera"><option value="">Camera nguồn</option></select></div><p id="summary">Đang tải…</p><p><a href="index.html">Báo cáo thử nghiệm</a> · <a href="measured-result.json">Số liệu</a></p></header><footer><span>Google Maps / Cesium ion · © OpenStreetMap contributors, ODbL. Ảnh và mẫu mesh nguồn không phải dữ liệu khảo sát. Vùng thiếu quan sát dùng vật liệu fallback.</span><span id="stats"></span></footer><script src="measured-viewer.js"></script><script src="measured-app.js"></script></html>''',encoding='utf-8')
    (run/'measured-app.js').write_text('''fetch('measured-scene.json').then(r=>r.json()).then(async data=>{await initMeasured(data);for(const b of data.city.buildings){const o=document.createElement('option');o.value=b.id;o.textContent=b.name;document.getElementById('object').appendChild(o);}for(let i=0;i<data.views.length;i++){const o=document.createElement('option');o.value='source:'+i;o.textContent=data.views[i].id+(data.views[i].held_out?' (validation)':'');document.getElementById('source-camera').appendChild(o);}document.getElementById('variant').onchange=e=>measuredVariant(e.target.value);document.getElementById('mode').onchange=e=>measuredMode(e.target.value);document.getElementById('object').onchange=e=>measuredSelect(e.target.value);document.getElementById('source-camera').onchange=e=>{if(e.target.value)measuredView(e.target.value)};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>measuredView(b.dataset.view));document.getElementById('summary').textContent=data.city.buildings.length+' công trình. Hình dạng và ảnh nguồn vẫn có sai số; xem vùng thiếu ảnh bằng chế độ kiểm tra.';setInterval(()=>document.getElementById('stats').textContent=JSON.stringify(measuredStats()),2000);}).catch(e=>document.getElementById('summary').textContent=e.message);''',encoding='utf-8')
    print(run/'viewer.html')


if __name__=='__main__':main()
